import{Mt as e,R as t,X as n,b as r,d as i,f as a,ht as o,p as s,u as c,v as l}from"./D1h5OiUR.js";import{n as u}from"./BliATjOS.js";import{t as d}from"./B1b5-9Ze.js";import{t as f}from"./BJwH8_ov.js";import{t as p}from"./BDNMzG2s.js";import{t as m}from"./KqaPPzJT.js";import{t as h}from"./NvPhdoFs.js";var g={weeklyTasks:[{nameProgram:`«Дневник питания: 2 дня под микроскопом»`,whatDoing:`В течение недели выберите 2 дня (например, вторник и пятницу) и запишите ВСЁ, что вы съели и выпили за эти дни. Без самообмана, без пропусков. Даже если это «просто печенька» или «чай с сахаром». Фиксируйте: завтрак, перекусы, обед, ужин, воду. В конце недели (в воскресенье) возьмите свои записи и проведите честный анализ: каких продуктов больше всего в рационе? хватает ли овощей и белка? есть ли вредные привычки (сладкое натощак, пропуск завтрака)? сколько воды вы реально пьёте? и самое главное — какие 3 изменения вы можете сделать уже на следующей неделе?`,whyDoing:`Без осознанности мы едим автоматически. Мы не замечаем, сколько на самом деле съедаем, когда перекусываем на бегу, и как много сахара попадает в организм через напитки и «безобидные» перекусы. Два дня записи — это зеркало вашего реального питания. Вы увидите свои паттерны: «я забываю завтракать», «в 16:00 я всегда хочу сладкого», «я пью всего 2 стакана воды в день». Три конкретных изменения на следующую неделю превращают анализ в действие. Знание без действия — просто информация. Анализ + 3 изменения = прогресс.`},{nameProgram:`«Цифровой и физический детокс: очистка пространства»`,whatDoing:`В течение недели провести тотальную ревизию своего физического пространства. Правило: всё, чем вы не пользовались последние 3 месяца, либо выбрасывается, либо отдаётся, либо убирается в дальний ящик. Комната (или рабочий стол) должна стать местом, где остаётся только то, что вам действительно нужно и приносит радость. Разбирайте по зонам: рабочий стол, шкаф, тумбочка, полки, ящики. Каждый день выделяйте 15–20 минут на одну зону. Не пытайтесь сделать всё за один день — это вызовет усталость и сопротивление. Важно не просто переложить вещи, а принять решение: оставить, выбросить или отдать.`,whyDoing:`Каждая вещь в вашем поле зрения занимает оперативную память мозга. Видимый беспорядок создаёт постоянный фоновый шум — мозг подсознательно обрабатывает эти сигналы, отвлекаясь от важного. Физический беспорядок напрямую связан с повышенным уровнем кортизола и снижением способности к концентрации. Когда вы убираете лишнее, вы освобождаете когнитивные ресурсы. Каждая выброшенная вещь — это один лишний стимул, переставший отвлекать. Через неделю вы заметите: голова стала яснее, решения принимаются быстрее, в пространстве появилось место для нового — буквально и метафорически.`},{nameProgram:`«Геометрия тела: осанка как гормональный переключатель»`,whatDoing:`В течение недели отслеживать и корректировать свою осанку в течение дня. Каждый час задавать себе вопрос: «Как я сейчас сижу/стою/хожу?» и исправлять: расправить плечи, опустить лопатки, поднять голову, выпрямить спину. Особое внимание трём ситуациям: положение за столом (экран на уровне глаз, локти под 90°, стопы на полу), положение в телефоне (поднять телефон до уровня глаз, не опускать голову вниз), положение во время ходьбы (смотреть вперёд, не вниз). Можно поставить напоминания в телефоне или использовать стикеры на рабочем месте. Главное — не просто исправлять один раз, а ловить себя на сутулости в течение всего дня.`,whyDoing:`Тело и психика неразрывно связаны. Поза власти (открытая, прямая спина, расправленные плечи) повышает уровень тестостерона на 20% и снижает кортизол (гормон стресса) на 25% всего за 2 минуты — это доказано в исследовании Гарвардского психолога Эми Кадди. Сгорбленная поза, наоборот, сигнализирует мозгу «я слаб, я в опасности» — и уровень стресса растёт. Когда вы выпрямляетесь, вы меняете гормональный фон, становитесь увереннее и спокойнее. Правильная осанка также улучшает дыхание (диафрагма не сдавлена), кровообращение и работу внутренних органов. Через неделю вы заметите: меньше болей в спине, больше энергии, уверенности, а взгляд в зеркало перестаёт вызывать желание сутулиться.`},{nameProgram:`«7 минут утром: неделя пробуждения»`,whatDoing:`Каждое утро в течение всей недели, с понедельника по воскресенье, выполнять 7-минутный комплекс сразу после пробуждения, до завтрака и до телефона. Это не тренировка, а настройка тела на день. Комплекс круговой: 6 упражнений по 30 секунд, отдых 10 секунд между упражнениями. Весь круг повторяется 2 раза. Между кругами — 30 секунд отдыха. Всё делается в комфортном темпе, без рывков. Если какое-то упражнение слишком сложное — делайте облегчённый вариант, но не пропускайте. Пропуск одного утра — это не страшно, но два пропуска подряд ломают привычку. Главное — начать, остальное приложится. Упражнения: 1. Приседания — 30 секунд (до комфортной глубины, спина прямая); 2. Отжимания с колен — 30 секунд (или от стены, если сложно); 3. Планка на прямых руках — 30 секунд (тело прямая линия); 4. Выпады назад — 30 секунд (поочерёдно, с контролем колена); 5. Скручивания лёжа — 30 секунд (поясница прижата к полу); 6. Супермен лёжа на животе — 30 секунд (руки вытянуты вперёд, одновременно подъём груди и ног).`,whyDoing:`Утром тело сковано после сна: мышцы укорочены, суставы обездвижены, кровообращение замедлено. Резкое вставание — стресс для позвоночника и сердечно-сосудистой системы. 7 минут мягкой, но активной работы включают все крупные группы мышц: ноги, руки, кор, спину. Круговая структура даёт лёгкую кардионагрузку, которая будит сердечно-сосудистую систему и разгоняет метаболизм. Это не тренировка на результат — это настройка тела на день. Каждый день вы укрепляете привычку, которая останется с вами надолго. Через неделю вы заметите: вставать легче, энергии больше, утренняя скованность ушла. И главное — вы докажете себе, что можете делать сложное ежедневно, даже когда очень не хочется.`}]},_=u(`weeklyTasks`,{state:()=>({completed:{}}),getters:{currentTask(){let e=this.currentWeek-1;return g.weeklyTasks[e%g.weeklyTasks.length]},currentWeek(){let e=localStorage.getItem(`recovery-start-date`);if(!e)return 1;let t=Math.floor((Date.now()-new Date(e).getTime())/(1e3*60*60*24));return Math.floor(t/7)+1},currentDayWithinWeek(){let e=localStorage.getItem(`recovery-start-date`);return e?Math.floor((Date.now()-new Date(e).getTime())/(1e3*60*60*24))%7+1:1},canComplete(){return this.currentDayWithinWeek>=6&&this.currentDayWithinWeek<=7}},actions:{completeCurrentTask(){this.completed[this.currentWeek]=!0},isCompleted(){return!!this.completed[this.currentWeek]},rewardEnergy(){let e=h();e.energy+=100}},persist:!0}),v={class:`page`},y={class:`header`},b={class:`subtitle`},x={class:`week-day`},S={class:`task-title`},C={class:`section`},w={class:`text`},T={class:`section`},E={class:`text`},D={key:1,class:`week-info`},O={key:2,class:`success-banner`},k=p(r({__name:`weekly`,setup(r){let u=_();function p(){u.canComplete&&(u.completeCurrentTask(),u.rewardEnergy())}return(r,h)=>{let g=d,_=f,k=m;return t(),s(`div`,v,[c(`div`,y,[h[0]||=c(`div`,{class:`title`},`Еженедельное задание`,-1),c(`div`,b,`Неделя `+e(o(u).currentWeek),1),c(`div`,x,`День `+e(o(u).currentDayWithinWeek)+` из 7`,1)]),l(_,{class:`task-card`},{default:n(()=>[h[3]||=c(`div`,{class:`badge`},`🎯 Задание недели`,-1),c(`div`,S,e(o(u).currentTask.nameProgram),1),c(`div`,C,[h[1]||=c(`div`,{class:`section-title`},`Что делать`,-1),c(`div`,w,e(o(u).currentTask.whatDoing),1)]),c(`div`,T,[h[2]||=c(`div`,{class:`section-title`},`Зачем это нужно`,-1),c(`div`,E,e(o(u).currentTask.whyDoing),1)]),o(u).isCompleted()?a(``,!0):(t(),i(g,{key:0,color:`primary`,unelevated:``,"no-caps":``,class:`complete-btn`,label:`Задание недели выполнено`,disable:!o(u).canComplete,onClick:p},null,8,[`disable`])),!o(u).canComplete&&!o(u).isCompleted()?(t(),s(`div`,D,` Выполнить задание можно на 6–7 день недели `)):(t(),s(`div`,O,`✅ Задание недели выполнено`))]),_:1}),l(k)])}}}),[[`__scopeId`,`data-v-82458c52`]]);export{k as default};